import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";import"./chunks/assets.qc2aQQfo.js";var i=JSON.parse(`{"title":"알림 수신 시간대 설정해보기","description":"알림 수신 요일·시간대 설정 기능을 구현하며 마주친 비트마스크 표현, 한국 달력의 일요일 시작 관행, 라이브러리·표준별 DayOfWeek 차이를 정리합니다.","frontmatter":{"title":"알림 수신 시간대 설정해보기","date":"2026-05-08T20:00+09:00","description":"알림 수신 요일·시간대 설정 기능을 구현하며 마주친 비트마스크 표현, 한국 달력의 일요일 시작 관행, 라이브러리·표준별 DayOfWeek 차이를 정리합니다.","tags":["Bitmask","DayOfWeek","PostgreSQL","UI"]},"headers":[],"relativePath":"posts/dayofweek-bitmask.md","filePath":"posts/dayofweek-bitmask.md","lastUpdated":1784671049000}`),a={name:`posts/dayofweek-bitmask.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="알림-수신-시간대-설정해보기" tabindex="-1">알림 수신 시간대 설정해보기 <a class="header-anchor" href="#알림-수신-시간대-설정해보기" aria-label="Permalink to “알림 수신 시간대 설정해보기”">​</a></h1><p>실무에서 <strong>알림 메시지를 어떤 요일·어떤 시간대에 수신할지</strong> 사용자가 직접 설정해야 한다는 요구사항이 있었어요. &quot;평일 업무 시간대에만 알림을 받을게요&quot; 같은 설정이죠. 단순해 보이지만 막상 구현하려고 보면 결정해야 할 사항들이 생각보다 많았어요.</p><p>이 글은 요구사항을 해결하면서 <strong>알게 된 정보들을 정리해 공유</strong> 해보려고 해요. 다루고자 하는 내용은 다음과 같아요.</p><ul><li>사용자가 선택한 요일을 어떻게 관리할까?</li><li>주의 시작은 어떻게 정해야 할까?</li><li>DayOfWeek 의 표준은 무엇인가?</li></ul><h2 id="_1-사용자가-선택한-요일을-어떻게-관리할까" tabindex="-1">1. 사용자가 선택한 요일을 어떻게 관리할까? <a class="header-anchor" href="#_1-사용자가-선택한-요일을-어떻게-관리할까" aria-label="Permalink to “1. 사용자가 선택한 요일을 어떻게 관리할까?”">​</a></h2><p>당연하게도 설계와 구현은 AI 에이전트에게 맡겼는데 사용자가 선택한 요일을 dayOfWeekMask 라는 필드를 두고 관리하더라고요. 저는 Boolean 배열을 사용해야 하지 않을까 생각했는데 비트마스크로 구현했더라고요. 그러면, 왜 비트마스크를 사용할까요?</p><p>비트마스크로 구현하면 매일과 평일 그리고 주말에 대한 표현을 비트 연산으로 빠르고 쉽게 판단할 수 있어요. 물론 비트로 관리하는 게 인간에게 코드 가독성을 주진 않아요.</p><h2 id="_2-주의-시작은-어떻게-정해야-할까" tabindex="-1">2. 주의 시작은 어떻게 정해야 할까? <a class="header-anchor" href="#_2-주의-시작은-어떻게-정해야-할까" aria-label="Permalink to “2. 주의 시작은 어떻게 정해야 할까?”">​</a></h2><p>AI 에이전트는 저에게 주의 시작(weekStart)에 대해서 결정을 요구했어요. 그래서 찾아보니 ISO 8601 표준은 월요일을 시작으로 하는데 달력처럼 일부에서는 일요일을 시작으로 하는 걸 볼 수 있어요.</p><blockquote><p>대한민국도 한 주의 시작은 월요일이지만 달력만큼은 일요일 시작으로 유지하고 있어요.</p></blockquote><p>그래서 기술적인 표준과 다르게 일반적인 사용자는 달력 순서에 익숙하다는 생각으로 weekStart를 0으로 두고 나중을 위한 유연한 설계로 남기기로 했어요.</p><h2 id="_3-dayofweek-의-표준은-무엇인가" tabindex="-1">3. DayOfWeek 의 표준은 무엇인가? <a class="header-anchor" href="#_3-dayofweek-의-표준은-무엇인가" aria-label="Permalink to “3. DayOfWeek 의 표준은 무엇인가?”">​</a></h2><p>하나의 웹 시스템을 구성하는 프론트엔드, 백엔드 그리고 데이터베이스 사이에도 표준은 갈렸어요. PostgreSQL 은 ISO 8601 표준에 따라 월요일을 주의 시작으로 하는 <code>isodow</code> 를 지원하지만 기본값은 일요일을 0으로 하는 <code>dow</code> 를 사용해요.</p><p>다만, 자바의 <code>DayOfWeek</code> 은 월요일(1)부터 시작하기 때문에 서비스 로직에서 무언가를 판단할 때에는 기준을 맞추는 게 중요해져요. 실무 프론트엔드에서 사용중인 Day.js 는 기본적으로는 일요일(0) 시작이지만 <code>isoWeekday()</code> 메서드를 통해 월요일(1)을 기준으로 할 수 있도록 지원해요.</p><h2 id="사용자가-보게될-결과물" tabindex="-1">사용자가 보게될 결과물 <a class="header-anchor" href="#사용자가-보게될-결과물" aria-label="Permalink to “사용자가 보게될 결과물”">​</a></h2><p><img src="/images/posts/dayofweek-bitmask/001.svg" alt="알림 수신 시간대 설정 UI 목업 — 요일 토글과 시작/종료 시각 입력" loading="lazy"></p><p>사용자가 보게 될 결과물은 <code>dayOfWeekMask</code> 와 <code>startTime</code>/<code>endTime</code> 두 시각 필드, 그리고 <code>weekStart</code> 가 결합된 토글 UI 로 단순합니다. 이 단순함을 유지하기 위해 어떤 결정들이 오갔는지는 사용자 화면 너머에 남아요.</p><h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="https://developer.mozilla.org/ko/docs/Web/JavaScript/Reference/Global_Objects/Date/getDay" target="_blank" rel="noreferrer">MDN — Date.prototype.getDay()</a></li><li><a href="https://day.js.org/docs/en/get-set/day" target="_blank" rel="noreferrer">Day.js — <code>.day()</code> / <code>.isoWeekday()</code></a></li><li><a href="https://www.postgresql.org/docs/current/functions-datetime.html#FUNCTIONS-DATETIME-EXTRACT" target="_blank" rel="noreferrer">PostgreSQL — <code>EXTRACT</code> (<code>dow</code>, <code>isodow</code>)</a></li><li><a href="https://docs.oracle.com/en/java/javase/25/docs/api/java.base/java/time/DayOfWeek.html" target="_blank" rel="noreferrer">Java — <code>java.time.DayOfWeek</code></a></li></ul>`,19)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};